'use client';
import React from 'react';

import { SkinTonePickerLocation } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// Narrow, touch-first: no Search (type-to-search is off with it), no
// section titles, 34px emojis.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

export function Shell({
  Root: RootComponent = Picker.Root,
  className,
}: ShellProps) {
  return (
    <div className="ios-phone">
      <div className="ios-sheet-host">
        <RootComponent appearance="default"
          className={className}
          skinTonePickerLocation={SkinTonePickerLocation.NONE}
        >
          <div className="ios-handle" />
          <Picker.Viewport>
            <Picker.List />
          </Picker.Viewport>
          <Picker.CategoryNav />
        </RootComponent>
      </div>
    </div>
  );
}

/* The surrounding mock app (shared by every stack variant). */
.ios-phone {
  position: relative;
  width: 340px;
  height: 560px;
  overflow: hidden;
  border-radius: 40px;
  background: linear-gradient(180deg, #8ec5fc, #e0c3fc);
  box-shadow: 0 0 0 10px #111, 0 20px 50px rgb(0 0 0 / 35%);
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Helvetica Neue',
    Arial, sans-serif;
}
.ios-handle {
  width: 36px;
  height: 5px;
  margin: 8px auto 6px;
  border-radius: 3px;
  background: #c7c7cc;
}
/* No section titles: hide them (the label-height token above is 0, so
   measurement and virtualization agree). */

/* The sheet's position belongs to the host; the picker fills it. */
.ios-sheet-host {
  position: absolute;
  inset: auto 0 0;
  height: 330px;
}

/* iOS — narrow bottom sheet on a phone: drag handle, no search, no section
   titles, larger touch targets, tabs at the bottom. */
/* Picker styles — the source of truth for every stack variant. */
.ios-sheet {
  --epr-bg-color: #f2f2f7;
  --epr-text-color: #3c3c43;
  --epr-highlight-color: #007aff;
  --epr-hover-bg-color: rgb(120 120 128 / 16%);
  --epr-focus-bg-color: rgb(120 120 128 / 20%);
  --epr-category-label-height: 0px;
  --epr-category-icon-active-color: #007aff;
  --epr-category-icon-inactive-color: #8e8e93;
  --epr-category-navigation-button-size: 26px;
  --epr-emoji-size: 34px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 12px;
  height: 100%;
  border-radius: 16px 16px 0 0;
  background: var(--epr-bg-color);
  box-shadow: 0 -4px 24px rgb(0 0 0 / 18%);
}
.ios-sheet [data-epr-part='category-label'] {
  display: none;
}
.ios-sheet [data-epr-part='emoji'] {
  border-radius: 10px;
}
.ios-sheet [data-epr-part='category-nav'] {
  border-top: 0.5px solid rgb(60 60 67 / 29%);
  background: rgb(249 249 249 / 94%);
}
.ios-sheet [data-epr-part='category-nav'] > * {
  padding: 8px 10px 22px;
}

/* Generated by scripts/generateRecipes.mjs from picker.css — do not edit. */
.picker {
  --epr-bg-color: #f2f2f7;
  --epr-text-color: #3c3c43;
  --epr-highlight-color: #007aff;
  --epr-hover-bg-color: rgb(120 120 128 / 16%);
  --epr-focus-bg-color: rgb(120 120 128 / 20%);
  --epr-category-label-height: 0px;
  --epr-category-icon-active-color: #007aff;
  --epr-category-icon-inactive-color: #8e8e93;
  --epr-category-navigation-button-size: 26px;
  --epr-emoji-size: 34px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 12px;
  height: 100%;
  border-radius: 16px 16px 0 0;
  background: var(--epr-bg-color);
  box-shadow: 0 -4px 24px rgb(0 0 0 / 18%);
}
.picker [data-epr-part='category-label'] {
  display: none;
}
.picker [data-epr-part='emoji'] {
  border-radius: 10px;
}
.picker [data-epr-part='category-nav'] {
  border-top: 0.5px solid rgb(60 60 67 / 29%);
  background: rgb(249 249 249 / 94%);
}
.picker [data-epr-part='category-nav'] > * {
  padding: 8px 10px 22px;
}
